type NodeSpec = [id: string, kind: NodeKind, label: string, technology: string, description: string, requirementFields?: string[]];
type EdgeSpec = [source: string, target: string, label: string, kind?: "data" | "control" | "network"];

function diagram(nodes: NodeSpec[], edges: EdgeSpec[]): DiagramModel {
  const provenance = { origin: "reference" as const };
  return {
    nodes: autoLayout(nodes.map(([id, kind, label, technology, description, requirementFields]) => ({ id, kind, label, technology, description, config: {}, provenance, requirementFields: requirementFields ?? [] }))),
    edges: edges.map(([source, target, label, kind]) => ({ id: `${source}__${target}`, source, target, label, kind: kind ?? "data", provenance })),
  };
}

const TITLES: Record<string, string> = {
  context: "Problem / context",
  concepts: "Core concepts",
  "how-it-works": "How it works",
  implementation: "Implementation steps",
  prerequisites: "Prerequisites",
  "best-practices": "Best practices",
  limitations: "Limitations / trade-offs",
  security: "Security",
  "cost-drivers": "Cost drivers",
  validation: "Validation",
};
const sections = (bodies: Record<string, string>): KnowledgeSection[] => Object.entries(bodies).map(([key, body]) => ({ key, title: TITLES[key] ?? key, body }));

const scenario = (slug: string, title: string, summary: string, tags: string[], sources: string[], attributes: KnowledgeAttributes, bodies: Record<string, string>): SeedItem => ({ slug, type: "scenario", title, summary, tags, sourceType: "vendor-official", sections: sections(bodies), attributes, sources });
const item = (type: string, slug: string, title: string, summary: string, tags: string[], sources: string[], bodies: Record<string, string>, attributes: KnowledgeAttributes = {}): SeedItem => ({ slug, type, title, summary, tags, sourceType: sources.length ? "vendor-official" : "unspecified", sections: sections(bodies), attributes, sources });

